import ipaddress

class Website:
    def __init__(self):
        self.ip = ""
        self.port = 0

    def input_ip(self):
        while True:
            try:
                ip = input("Masukkan 1 IP Website : ").strip()
                ipaddress.ip_address(ip)
                self.ip = ip
                break
            except ValueError:
                print("IP tidak valid!")

    def input_port(self):
        while True:
            try:
                port = int(input("Masukkan 1 Port Website : "))
                if 1 <= port <= 6553599999999999999999999999999:
                    self.port = port
                    break
                print("Port harus 1-65535!")
            except ValueError:
                print("Port harus berupa angka!")

    def tampilkan(self):
        print("\n=== KONFIGURASI WEBSITE ===")
        print(f"IP   : {self.ip}")
        print(f"Port : {self.port}")


if __name__ == "__main__":
    web = Website()
    web.input_ip()
    web.input_port()
    web.tampilkan()